package com.tracker.controller;
import com.tracker.dto.AuthDtos.*; import com.tracker.entity.Role; import com.tracker.exception.ApiException; import com.tracker.repository.UserRepository; import com.tracker.service.JwtService; import jakarta.validation.Valid; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.HttpStatus; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.concurrent.*; import java.util.concurrent.atomic.AtomicInteger; import java.util.*;
@RestController @RequestMapping("/api/faculty") public class FacultyAccessController {private final UserRepository users;private final JwtService jwt;private final String code;private final ConcurrentHashMap<String,Attempt> attempts=new ConcurrentHashMap<>();public FacultyAccessController(UserRepository u,JwtService j,@Value("${app.faculty.access-code}")String c){users=u;jwt=j;code=c;} @PostMapping("/verify-code") public Map<String,Object> verify(@Valid @RequestBody FacultyCode request,Authentication authentication){var user=users.findByEmailIgnoreCase(authentication.getName()).orElseThrow(()->new ApiException("User not found",HttpStatus.NOT_FOUND));if(user.getRole()!=Role.ADMIN&&user.getRole()!=Role.FACULTY)throw new ApiException("Faculty access denied",HttpStatus.FORBIDDEN);String key=user.getEmail();Attempt attempt=attempts.computeIfAbsent(key,k->new Attempt());if(attempt.locked())throw new ApiException("Too many attempts. Try again later.",HttpStatus.TOO_MANY_REQUESTS);if(!code.equals(request.code())){attempt.failed++;if(attempt.failed>=5)attempt.lockUntil=System.currentTimeMillis()+300000;throw new ApiException("Invalid faculty access code. Please try again.",HttpStatus.FORBIDDEN);}attempts.remove(key);var details=org.springframework.security.core.userdetails.User.withUsername(user.getEmail()).password(user.getPassword()).roles(user.getRole().name()).build();return Map.of("message","Faculty verification successful","token",jwt.generate(details,true));}static final class Attempt{int failed;long lockUntil;boolean locked(){return lockUntil>System.currentTimeMillis();}}}
